<?php if (!$catalog['books']): ?>
    <div class="empty-state"><?= icon('book') ?><h3><?= $catalog['query'] === '' ? 'O próximo capítulo começa aqui' : 'Nenhum livro encontrado' ?></h3><p><?= $catalog['query'] === '' ? 'Cadastre seu primeiro livro para começar a organizar o acervo.' : 'Tente outro título ou limpe a busca para ver todo o acervo.' ?></p><a class="button <?= $catalog['query'] === '' ? 'primary' : 'secondary' ?>" href="<?= $catalog['query'] === '' ? 'livro.php' : 'index.php' ?>"><?= $catalog['query'] === '' ? 'Cadastrar primeiro livro' : 'Limpar busca' ?></a></div>
<?php else: ?>
    <div class="table-scroll" tabindex="0" role="region" aria-label="Tabela de livros; deslize horizontalmente em telas pequenas">
        <table><caption class="sr-only">Livros do acervo da Editora Fonteles</caption><thead><tr><th scope="col">Livro / autor</th><th scope="col">Categoria</th><th scope="col">Preço unitário</th><th scope="col">Estoque</th><th scope="col" class="actions-heading">Ações</th></tr></thead><tbody>
        <?php foreach ($catalog['books'] as $book): ?>
            <tr><td><div class="book-cell"><span class="book-spine tone-<?= (int) $book['id'] % 4 ?>" aria-hidden="true"><?= icon('book') ?></span><div><a class="book-title" href="livro.php?id=<?= (int) $book['id'] ?>"><?= e($book['titulo']) ?></a><span class="book-author"><?= e($book['autor']) ?></span></div></div></td><td><span class="category-tag"><?= e($book['categoria']) ?></span></td><td class="numeric"><?= money($book['preco']) ?></td><td><span class="stock <?= (int) $book['quantidade'] === 0 ? 'zero' : '' ?>"><span class="status-dot"></span><?= number_format((int) $book['quantidade'], 0, ',', '.') ?> un.</span></td><td><div class="row-actions"><a class="icon-button" href="livro.php?id=<?= (int) $book['id'] ?>" aria-label="Editar <?= e($book['titulo']) ?>" title="Editar livro"><?= icon('edit') ?></a><a class="icon-button delete-link" href="excluir.php?id=<?= (int) $book['id'] ?>" data-delete-id="<?= (int) $book['id'] ?>" data-delete-title="<?= e($book['titulo']) ?>" aria-label="Excluir <?= e($book['titulo']) ?>" title="Excluir livro"><?= icon('trash') ?></a></div></td></tr>
        <?php endforeach; ?>
        </tbody></table>
    </div>
<?php endif; ?>
<div class="table-footer"><span><?= $catalog['total'] ? (($catalog['page'] - 1) * 8 + 1) . '–' . min($catalog['page'] * 8, $catalog['total']) . ' de ' . $catalog['total'] . ' título(s)' : '0 títulos' ?></span><nav class="pagination" aria-label="Paginação do acervo"><?php $previous = http_build_query(['q' => $catalog['query'], 'pagina' => max(1, $catalog['page'] - 1)]); $next = http_build_query(['q' => $catalog['query'], 'pagina' => min($catalog['pages'], $catalog['page'] + 1)]); ?><?php if ($catalog['page'] > 1): ?><a class="page-button" href="index.php?<?= e($previous) ?>" data-page-link aria-label="Página anterior">←</a><?php else: ?><span class="page-button disabled" aria-disabled="true">←</span><?php endif; ?><span class="page-label">Página <?= $catalog['page'] ?> de <?= $catalog['pages'] ?></span><?php if ($catalog['page'] < $catalog['pages']): ?><a class="page-button" href="index.php?<?= e($next) ?>" data-page-link aria-label="Próxima página">→</a><?php else: ?><span class="page-button disabled" aria-disabled="true">→</span><?php endif; ?></nav></div>
